INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('61ba051a-d1e0-4ecc-8f7e-d6ab5980e007', 'ad0fd512-0f1f-46bf-b4f5-6524eefcb067', 'Nitrofurantoin requires eGFR >= 45 mL/min. Uncomplicated female lower UTI treatment duration is 3 days.', 'Trimethoprim can artificially elevate serum creatinine by inhibiting tubular secretion without altering true GFR. Reference: NICE NG109 & UKHSA Primary Care Antimicrobial Guidance.', 'NICE NG109 & UKHSA Primary Care Antimicrobial Guidance', 1789655696, 1789655696);
