INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('23a4c97c-0f60-4437-8a91-b82aac4215af', 'bdf0d51e-5065-4ced-889d-767f748ab0c2', 'D', 'Amoxicillin 500 mg three times daily for 7 days', 0, 'Deprecated due to high nationwide E. coli resistance rates (> 50%).', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a1097e9b-fda3-4e91-bbcb-9e4c63a48dca', 'bdf0d51e-5065-4ced-889d-767f748ab0c2', 'E', 'Extend antibiotic duration to 14 days without urine culture review', 0, 'Excessive duration promotes antimicrobial resistance; standard female lower UTI duration is 3 days.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('f7e8f129-419b-41f9-9f24-8ee1d3e8d645', 'bdf0d51e-5065-4ced-889d-767f748ab0c2', 'Nitrofurantoin requires eGFR >= 45 mL/min. Uncomplicated female lower UTI treatment duration is 3 days.', 'Trimethoprim can artificially elevate serum creatinine by inhibiting tubular secretion without altering true GFR. Reference: NICE NG109 & UKHSA Primary Care Antimicrobial Guidance.', 'NICE NG109 & UKHSA Primary Care Antimicrobial Guidance', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('fe9baa5e-71a4-4823-b583-c750a4fac95c', 'bdf0d51e-5065-4ced-889d-767f748ab0c2', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('f2d63aa2-2b92-401b-a045-d88b93365911', 'ACP-Q-0641', 1, 'published', 'p-mpharm', 'sub-asthma', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('5a91d985-5c63-41b4-b440-3d4e0495230d', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'A 22-year-old female patient A 28-year-old adult with asthma using Beclometasone dipropionate 100 mcg twice daily reports using their Salbutamol inhaler 4 times a week, with night-time waking once weekly. Inhaler technique is confirmed satisfactory. (Case Ref: RESPIRATORY-0641). Relevant physiological and medication history have been reviewed.', 'What is the most appropriate next step in pharmacological management according to BTS/SIGN guidance?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2eeb73aa-9bb9-4b54-b463-2d89a01e483a', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'A', 'Add an Inhaled Long-Acting Beta2 Agonist (LABA) in a fixed-dose combination inhaler with Low-Dose ICS', 1, 'Correct. For uncontrolled asthma on low-dose ICS, adding a LABA to ICS (often as maintenance and reliever therapy MART) is the primary evidence-based step before increasing ICS dose.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('45f108b2-234c-4912-b303-93dba374fefc', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'B', 'Increase Beclometasone monotherapy to 400 mcg twice daily without adding LABA', 0, 'Sub-optimal. Adding a LABA is more effective than doubling the steroid dose alone and causes fewer systemic steroid adverse effects.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('deb82772-adca-4d6c-8e89-f930d0bbc50f', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'C', 'Prescribe Salmeterol LABA as a standalone separate inhaler alongside SABA', 0, 'Dangerous and contraindicated. LABA monotherapy without adequate ICS is associated with severe asthma exacerbations and death (MHRA black box warning).', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4c349a6a-44ac-40a6-bc6a-3e8f37b65425', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'D', 'Initiate oral Theophylline 200 mg twice daily', 0, 'Deprecated early-line choice. Theophylline has narrow therapeutic index and significant drug interactions.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0315ba13-28ff-475e-8d45-1652a522728d', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'E', 'Prescribe short course of Oral Prednisolone 40 mg daily without reviewing maintenance therapy', 0, 'Inappropriate for chronic sub-optimal control without severe acute exacerbation; addresses symptoms without fixing underlying baseline deficit.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('d20dc9e6-598c-4673-8b8a-6731a62f50b4', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'Always pair LABA with ICS (preferably in a single combination device). Never use LABA monotherapy in asthma.', 'MART (Maintenance and Reliever Therapy) reduces oral corticosteroid courses and hospitalisations. Reference: BTS/SIGN British Guideline on the Management of Asthma & NICE NG80.', 'BTS/SIGN British Guideline on the Management of Asthma & NICE NG80', 1789655696, 1789655696);
