INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0cb68b4f-054b-44a6-b2d7-600891a72134', 'bca5c4ee-066b-4126-9ea5-fd5b1f803f27', 'A', 'Add an Inhaled Long-Acting Beta2 Agonist (LABA) in a fixed-dose combination inhaler with Low-Dose ICS', 1, 'Correct. For uncontrolled asthma on low-dose ICS, adding a LABA to ICS (often as maintenance and reliever therapy MART) is the primary evidence-based step before increasing ICS dose.', 0, 1789655696);
