INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ef71c6f8-eb93-41c7-b8ba-0c4ab4e7e5e0', 'e539ea15-0027-4b45-870c-04b7b989930a', 'A', 'Add an Inhaled Long-Acting Beta2 Agonist (LABA) in a fixed-dose combination inhaler with Low-Dose ICS', 1, 'Correct. For uncontrolled asthma on low-dose ICS, adding a LABA to ICS (often as maintenance and reliever therapy MART) is the primary evidence-based step before increasing ICS dose.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('defe7c56-411f-4ca8-8cf1-0dc68ab64755', 'e539ea15-0027-4b45-870c-04b7b989930a', 'B', 'Increase Beclometasone monotherapy to 400 mcg twice daily without adding LABA', 0, 'Sub-optimal. Adding a LABA is more effective than doubling the steroid dose alone and causes fewer systemic steroid adverse effects.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6d668951-484e-4eb5-bb7c-72dfab643541', 'e539ea15-0027-4b45-870c-04b7b989930a', 'C', 'Prescribe Salmeterol LABA as a standalone separate inhaler alongside SABA', 0, 'Dangerous and contraindicated. LABA monotherapy without adequate ICS is associated with severe asthma exacerbations and death (MHRA black box warning).', 2, 1789655696);
