INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('a1975605-5925-4887-abce-1fc2b139388b', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'A 22-year-old female patient A 58-year-old patient with type 2 diabetes and a history of myocardial infarction 2 years ago has an HbA1c of 64 mmol/mol on Metformin 1 g twice daily. Current eGFR is 68 mL/min. (Case Ref: ENDOCRINE-0781). Relevant physiological and medication history have been reviewed.', 'Which agent should be introduced next according to NICE NG28?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d89cea4a-0640-4f07-a571-6dbeb15e65e1', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'A', 'Add an SGLT2 inhibitor with proven cardiovascular benefit (e.g. Empagliflozin 10 mg or Dapagliflozin 10 mg daily)', 1, 'Correct. For patients with T2DM and established CVD, NICE recommends introducing an SGLT2 inhibitor with proven cardiovascular benefit alongside metformin.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d160f951-e9aa-4137-82c3-4ef722a26139', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'B', 'Add Gliclazide 40 mg once daily with breakfast', 0, 'Sub-optimal. Sulfonylureas improve glycaemia but lack cardiorenal protective outcome benefits and increase hypoglycaemia/weight gain risk.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('225bcd90-3c29-4d2e-ba06-73825253bb30', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'C', 'Add Pioglitazone 15 mg daily in a patient with NYHA Class III heart failure', 0, 'Strictly contraindicated. Pioglitazone causes fluid retention and precipitates or worsens heart failure.', 2, 1789655696);
